example.code:
const order = { paying: false, paid: false, cancelled: false, attempts: 0 };

function charge() { order.attempts += 1; console.log('charge', order.attempts); }
function checkout() { order.paying = true; charge(); }
function onCharged() { order.paid = true; }  // paying stays true
function onTimeout() { if (order.paying && order.attempts < 3) charge(); }
function cancel() { order.cancelled = true; }

checkout();
onCharged(); // the payment service answers
onTimeout(); // the timer nobody cleared fires anyway
cancel();    // nothing stops a cancel after payment
console.log(order);

